'use strict';
const statusNode = document.getElementById('status');
const plot = document.getElementById('plot');
const colors = [[0,'#13384e'],[.35,'#228f92'],[.65,'#8bd1b1'],[1,'#f9cc77']];
const views = {
  map:['THE CARTOGRAPHIC VIEW','A field, made visible','A contour map of our fictional landscape. Lines join equal elevations; color fills the intervals. Both horizontal coordinates and elevation are in metres.','Hover for coordinates and elevation. Zoom with the toolbar.','04-terrain-and-rasters','terrain'],
  terrain:['THE SURFACE VIEW','Relief, with perspective','Rotate the same 3,721 R-generated elevations. Perspective can make a ridge look steep; numeric slope belongs to the underlying grid.','Drag to rotate; use the slider for a keyboard-controlled camera.','04-terrain-and-rasters','terrain'],
  scene:['THE LAYERED VIEW','A route above the ridges','A fictional drone route follows the analytic terrain at a clearance of 140 m at each sampled waypoint. The orange line is computed in R.','Rotate to inspect occlusion. The displayed terrain mesh interpolates grid samples.','05-three-dimensional-scenes','flight'],
  globe:['THE SPHERICAL VIEW','The long way round?','A great-circle arc links two invented waypoints on a mathematical sphere. The sphere has no copied coastline or texture. Chapter 6 computes the spherical distance.','Rotate the globe to inspect the route; the slider changes longitude of view.','06-globes-and-great-circles','route'],
  evidence:['THE EVIDENCE VIEW','A threshold is a choice','One hundred fictional environmental-index readings, ranked by value. Orange points meet the illustrative threshold of 48. This threshold is not a risk standard.','Hover for site IDs and values. Download the data to audit the ranking.','09-capstone','sites']
};
let current = 'map', dataset;
async function csv(name) {
  const response = await fetch(`data/${name}.csv`);
  if (!response.ok) throw new Error(`Could not load ${name}: HTTP ${response.status}`);
  // R write.csv exports these deliberately simple fields: no embedded commas/newlines.
  const lines = (await response.text()).trim().split(/\r?\n/);
  const headers = lines.shift().replaceAll('"','').split(',');
  return lines.map(line => Object.fromEntries(line.split(',').map((v,i) =>
    [headers[i], Number.isFinite(Number(v)) ? Number(v) : v.replaceAll('"','')])));
}
function camera() {
  const a = Number(document.getElementById('angle').value)*Math.PI/180;
  return {eye:{x:1.65*Math.cos(a),y:1.65*Math.sin(a),z:current==='globe'?.65:1.25}};
}
function traces() {
  const {terrain,flight,route,sites} = dataset;
  const x=[...new Set(terrain.map(r=>r.x))], y=[...new Set(terrain.map(r=>r.y))];
  const z=y.map((_,j)=>terrain.slice(j*x.length,(j+1)*x.length).map(r=>r.z));
  const surface={type:'surface',x,y,z,colorscale:colors,colorbar:{title:{text:'Elevation (m)'},thickness:12},hovertemplate:'x %{x:.0f} m<br>y %{y:.0f} m<br>height %{z:.1f} m<extra></extra>'};
  if(current==='map') return [{...surface,type:'contour',contours:{coloring:'heatmap',showlabels:true},line:{color:'#163747',width:.7}}];
  if(current==='terrain') return [surface];
  if(current==='scene') return [surface,{type:'scatter3d',mode:'lines',x:flight.map(r=>r.x),y:flight.map(r=>r.y),z:flight.map(r=>r.altitude),line:{color:'#ffad4c',width:6},name:'Fictional drone',hovertemplate:'Height %{z:.1f} m<extra>140 m sampled clearance</extra>'}];
  if(current==='evidence') {
    const ranked=[...sites].sort((a,b)=>a.index-b.index);
    return [{type:'scatter',mode:'markers',x:ranked.map((_,i)=>i+1),y:ranked.map(r=>r.index),text:ranked.map(r=>r.id),marker:{size:8,color:ranked.map(r=>r.index>=48?'#ffc66c':'#73d5c6')},hovertemplate:'%{text}<br>Rank %{x}<br>Index %{y:.2f}<extra></extra>'}];
  }
  const gx=[],gy=[],gz=[];
  for(let j=0;j<=36;j++) {
    const lat=-Math.PI/2+j*Math.PI/36; gx[j]=[];gy[j]=[];gz[j]=[];
    for(let i=0;i<=72;i++) {const lon=i*2*Math.PI/72;gx[j].push(Math.cos(lat)*Math.cos(lon));gy[j].push(Math.cos(lat)*Math.sin(lon));gz[j].push(Math.sin(lat));}
  }
  const sphere={type:'surface',x:gx,y:gy,z:gz,surfacecolor:gz.map(row=>row.map(()=>0)),colorscale:[[0,'#21747d'],[1,'#21747d']],showscale:false,hoverinfo:'skip',lighting:{ambient:.65,diffuse:.6}};
  const arc={type:'scatter3d',mode:'lines',x:route.map(r=>r.x*1.008),y:route.map(r=>r.y*1.008),z:route.map(r=>r.z*1.008),line:{color:'#ffc66c',width:7},hoverinfo:'skip',name:'Great-circle arc'};
  const graticule={type:'scatter3d',mode:'lines',x:[],y:[],z:[],line:{color:'#72c0bd',width:1},hoverinfo:'skip',showlegend:false};
  for(let lat=-60;lat<=60;lat+=30){for(let lon=-180;lon<=180;lon+=3){const p=lat*Math.PI/180,l=lon*Math.PI/180;graticule.x.push(1.003*Math.cos(p)*Math.cos(l));graticule.y.push(1.003*Math.cos(p)*Math.sin(l));graticule.z.push(1.003*Math.sin(p));}graticule.x.push(null);graticule.y.push(null);graticule.z.push(null);}
  return [sphere,graticule,arc];
}
async function render(name) {
  current=Object.hasOwn(views,name)?name:'map';
  const [kind,title,description,interaction,chapter,dataName]=views[current];
  for(const [id,text] of Object.entries({'view-kind':kind,'view-title':title,description,interaction}))document.getElementById(id).textContent=text;
  document.getElementById('notebook').href=`../lite/lab/index.html?path=${chapter}.ipynb`;
  document.getElementById('data-link').href=`data/${dataName}.csv`;
  document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===current)));
  const is3d=['terrain','scene','globe'].includes(current);
  document.getElementById('angle').hidden=!is3d;document.getElementById('angle-label').hidden=!is3d;
  const axis={gridcolor:'#294653',zerolinecolor:'#294653',color:'#b8cbd2'};
  const layout={paper_bgcolor:'#0b2635',plot_bgcolor:'#0b2635',font:{family:'system-ui, sans-serif',color:'#dce8e9'},margin:{l:65,r:35,t:35,b:60},showlegend:false,
    xaxis:{...axis,title:{text:current==='evidence'?'Rank':'Local x (m)'}},yaxis:{...axis,title:{text:current==='evidence'?'Index (arbitrary units)':'Local y (m)'},...(current==='map'?{scaleanchor:'x',scaleratio:1}:{})},
    scene:{camera:camera(),aspectmode:'data',xaxis:{...axis,title:{text:'x (m)'},visible:current!=='globe'},yaxis:{...axis,title:{text:'y (m)'},visible:current!=='globe'},zaxis:{...axis,title:{text:'Height (m)'},visible:current!=='globe'}},
    shapes:current==='evidence'?[{type:'line',x0:1,x1:100,y0:48,y1:48,line:{color:'#ffc66c',dash:'dot'}}]:[]};
  if(current==='globe')layout.scene.aspectmode='cube';
  await Plotly.react(plot,traces(),layout,{responsive:true,displaylogo:false,scrollZoom:false});
  statusNode.textContent='Ready · Original R-generated simulation · See chapter for units, assumptions, and checks.';
}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.view;}));
window.addEventListener('hashchange',()=>{if(dataset)render(location.hash.slice(1)).catch(showError);});
document.getElementById('angle').addEventListener('input',e=>{document.getElementById('angle-value').textContent=`${e.target.value}°`;if(dataset&&window.Plotly)Plotly.relayout(plot,{'scene.camera':camera()});});
function showError(error){statusNode.textContent=`Interactive view unavailable: ${error.message}. Read the Book or download the CSV data above.`;console.error(error);}
(async()=>{if(!window.Plotly)throw new Error('Plotly CDN did not load');const names=['terrain','flight','route','sites'];const values=await Promise.all(names.map(csv));dataset=Object.fromEntries(names.map((n,i)=>[n,values[i]]));await render(location.hash.slice(1)||'map');})().catch(showError);
